function cartTotal(items) {
  let total = 0n;
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  for (const item of items) {
    const priceCents = item?.priceCents;
    const quantity = item?.quantity;
    if (!Number.isSafeInteger(priceCents) || priceCents < 0 ||
        !Number.isSafeInteger(quantity) || quantity < 0) {
      throw new RangeError('priceCents and quantity must be non-negative safe integers');
    }
    total += BigInt(priceCents) * BigInt(quantity);
    if (total > max) {
      throw new RangeError('Cart total exceeds the safe integer range');
    }
  }
  return Number(total);
}

tests:
const assert = require('node:assert/strict');
assert.equal(cartTotal([]), 0);
assert.equal(cartTotal([{ priceCents: 199, quantity: 2 }, { priceCents: 50, quantity: 3 }]), 548);
assert.equal(cartTotal([{ priceCents: 100, quantity: 0 }]), 0);
assert.equal(cartTotal([{ priceCents: 0, quantity: Number.MAX_SAFE_INTEGER }]), 0);
assert.equal(cartTotal([{ priceCents: Number.MAX_SAFE_INTEGER, quantity: 1 }]), Number.MAX_SAFE_INTEGER);
assert.equal(cartTotal([{ priceCents: Number.MAX_SAFE_INTEGER, quantity: 0 }]), 0);

for (const field of ['priceCents', 'quantity']) {
  for (const value of [undefined, null, -1, 0.5, NaN, Infinity, -Infinity, '1', true, 1n, {}, Number.MAX_SAFE_INTEGER + 1]) {
    const item = { priceCents: 0, quantity: 0, [field]: value };
    assert.throws(() => cartTotal([item]), RangeError);
  }
}
for (const item of [null, undefined, {}, { priceCents: 1 }, { quantity: 1 }]) {
  assert.throws(() => cartTotal([item]), RangeError);
}

assert.throws(() => cartTotal([{ priceCents: Number.MAX_SAFE_INTEGER, quantity: 2 }]), RangeError);
assert.throws(() => cartTotal([{ priceCents: Number.MAX_SAFE_INTEGER, quantity: 1 }, { priceCents: 1, quantity: 1 }]), RangeError);
const items = Object.freeze([Object.freeze({ priceCents: 125, quantity: 2 }), Object.freeze({ priceCents: 99, quantity: 0 })]);
assert.equal(cartTotal(items), 250);
assert.deepEqual(items, [{ priceCents: 125, quantity: 2 }, { priceCents: 99, quantity: 0 }]);
